/**
 * Reference vectors from the Python sources nextdraw 1.7.5 uses
 * (ink_extensions, plotink, nextdrawcore, CPython random), for the helper
 * unit tests. Generated by test/oracle/digest_vectors.py into
 * test/fixtures/digest-vectors.json; regenerate rather than edit. `libm`
 * lists every sin/cos/tan/acos call made while generating, with CPython's
 * result.
 */

import { readFileSync } from "node:fs";

const SPECIAL: Record<string, number> = {
  nan: NaN,
  inf: Infinity,
  "-inf": -Infinity,
};

export const VECTORS: Record<string, unknown> = JSON.parse(
  readFileSync(
    new URL("../fixtures/digest-vectors.json", import.meta.url),
    "utf8"
  ),
  (_key, value) =>
    value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    "__float__" in value
      ? SPECIAL[value.__float__ as string]
      : value
);
